// Treat normal greetings and common typing variations as a new-conversation signal.
// Examples: hello, hellow, helo, hi, hey, good morning, good afternoon, etc.
const greetingRegex = /^(?:h+e+l+l+o+|h+e+l+o+|h+i+|h+e+y+|good\s+(?:morning|afternoon|evening)|namaste|hola|greetings|howdy)\b[\s!,.:-]*/i;
const found = greetingRegex.test(text);

return [{json: {
