const d = $input.first().json;
const text = String(d.message_text || '').toLowerCase().trim();

const courseKw = [
  'interested in', 'want to know', 'want to join', 'looking for a course',
  'tell me about', 'course', 'program', 'ui/ux', 'uiux', 'full stack',
  'fullstack', 'ai automation', 'web dev', 'data science', 'digital marketing',
  'python', 'java', 'react', 'angular', 'machine learning', 'graphic design',
  'admission', 'enroll', 'join'
];

const phoneReg = /\+?\d[\d\s\-()]{8,}\d/;
const emailReg = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i;
const contactKw = [
  'my number', 'my phone', 'my email', 'phone:', 'email:',
  'mobile:', 'contact:', 'here is my'
];

const isCourse = courseKw.some(k => text.includes(k));
const isContact =
  phoneReg.test(text) ||
  emailReg.test(text) ||
  contactKw.some(k => text.includes(k));

let messageType = 'other';
if (isCourse) messageType = 'course_inquiry';
else if (isContact) messageType = 'contact_reply';

return [{json: {
  Telegram_ID: d.Telegram_ID || '',
  Telegram_Username: d.Telegram_Username || '',
  Chat_ID: d.Chat_ID || '',
  Student_Name: d.Student_Name || '',
  message_text: d.message_text || '',
  start_param: d.start_param || '',
  Source: d.Source || 'Telegram',
  message_type: messageType
}}];

const d = $input.first().json;
const text = d.message_text || '';
const pm = text.match(/(\+?[\d][\d\s\-\(\)]{8,}[\d])/);
const em = text.match(/[\w._%+\-]+@[\w.\-]+\.[a-zA-Z]{2,}/);
const phone = pm ? pm[0].replace(/[\s\-\(\)]/g, '') : '';
const email = em ? em[0] : '';
return [{json: {
