  start_param: d.start_param || '',
  Source: d.Source,
  Phone: phone,
  Email: email,
  Inquiry_Type: 'Course Inquiry'
}}];

const rows = $input.all().map(i => i.json || {});
const contact = $('09 Extract Contact Details').first().json || {};

const norm = v => String(v ?? '').trim().toLowerCase();
const digits = v => String(v ?? '').replace(/\D/g,'');
const incomingTelegram = norm(contact.Telegram_ID);
const incomingName = norm(contact.Student_Name);
const incomingPhone = digits(contact.Phone);
const incomingEmail = norm(contact.Email);

const active = rows.filter(r => {
  const status = norm(r.Status || 'Active');
  return String(r.Lead_ID || '').trim() !== '' && status !== 'closed';
});

const matches = active.filter(r => {
  const rowTelegram = norm(r.Telegram_ID || r.Telegram_User_ID);
  const rowName = norm(r.Student_Name);
  const rowPhone = digits(r.Phone);
  const rowEmail = norm(r.Email);

  const phoneConflict = incomingPhone && rowPhone && incomingPhone !== rowPhone;
  const emailConflict = incomingEmail && rowEmail && incomingEmail !== rowEmail;
  if (phoneConflict || emailConflict) return false;

  const phoneMatch = incomingPhone && rowPhone && incomingPhone === rowPhone;
  const emailMatch = incomingEmail && rowEmail && incomingEmail === rowEmail;
  const telegramNameMatch =
    incomingTelegram && rowTelegram === incomingTelegram &&
    incomingName && rowName === incomingName;

  return phoneMatch || emailMatch || telegramNameMatch;
});

matches.sort((a,b) => {
  const score = r => {
    const rp = digits(r.Phone), re = norm(r.Email), rt = norm(r.Telegram_ID || r.Telegram_User_ID);
    return (incomingPhone && rp === incomingPhone ? 4 : 0) +
           (incomingEmail && re === incomingEmail ? 4 : 0) +
           (incomingTelegram && rt === incomingTelegram ? 2 : 0) +
           (incomingName && norm(r.Student_Name) === incomingName ? 1 : 0);
  };
  return score(b)-score(a);
});

if (matches.length) {
  return [{json:{...matches[0], match_found:true}}];
}

return [{json:{
