  admissionDate = indiaDate;
}

const previousStatus = (existingAdm && existingAdm.Status)
  ? String(existingAdm.Status) : String(lead.Status || 'NEW');

return [{json: {
  Admission_ID: admissionId,
  Lead_ID: leadId,
  Student_Name: studentName,
  Course: course,
  Counselor: counselor,
  Status: newStatus,
  Payment_Status: paymentStatus,
  Admission_Date: admissionDate,
  Updated_At: indiaDateTime,
  new_status: newStatus,
  previous_status: previousStatus,
  callback_query_id: normalizeData.callback_query_id,
  counselor_telegram_id: normalizeData.counselor_telegram_id,
  india_date: indiaDate,
  india_time: indiaTime
}}];

const normalize = $('82 Normalize Admission Status').first().json;
const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });
return [{json: {
  status: 'ERROR',
  error_type: 'LEAD_NOT_FOUND',
  error_message: 'Lead ID ' + normalize.Lead_ID + ' not found in Master_Lead. Admission update aborted.',
  Lead_ID: normalize.Lead_ID,
  callback_query_id: normalize.callback_query_id,
  timestamp: now
}}];
